/**
 * Gmail's wire shapes, generated by Google from the API's Discovery document
 * (@googleapis/gmail) rather than written here, so a misspelt or renamed field
 * is a compile error. Type-only: nothing of that package runs, the requests
 * stay ours (infra/). Every field is optional and may be null, because that is
 * what the schema promises; the code reading them says what it does when one
 * is missing.
 *
 * The one import in domain/, on purpose: it is types, and they describe the
 * outside world this layer's rules are about.
 */
import type { DeepReadonly } from "@foreverworks/mcp-kit";
import type { gmail_v1 } from "@googleapis/gmail";

export type RawMessage = DeepReadonly<gmail_v1.Schema$Message>;
export type RawThread = DeepReadonly<gmail_v1.Schema$Thread>;
export type MimePart = DeepReadonly<gmail_v1.Schema$MessagePart>;
export type RawLabel = DeepReadonly<gmail_v1.Schema$Label>;
export type RawDraft = DeepReadonly<gmail_v1.Schema$Draft>;
export type Profile = DeepReadonly<gmail_v1.Schema$Profile>;
export type SendAs = DeepReadonly<gmail_v1.Schema$SendAs>;
export type ThreadListPage = DeepReadonly<gmail_v1.Schema$ListThreadsResponse>;
export type HistoryPage = DeepReadonly<gmail_v1.Schema$ListHistoryResponse>;
export type DraftListPage = DeepReadonly<gmail_v1.Schema$ListDraftsResponse>;
export type RawFilter = DeepReadonly<gmail_v1.Schema$Filter>;
export type FilterList = DeepReadonly<gmail_v1.Schema$ListFiltersResponse>;
